/* RENDERING — all screens read the same central state and calculation engine. */
function renderMonthly(){
 const month=currentMonth(),m=E.calculateMonthlySummary(state,month),days=E.dailyBalances(state,month),spend=E.TYPES.slice(1).map(t=>({name:t,value:m.groups[t].actual,color:colors[t]}));
 let html=heading('PLAN · TRACK · ADJUST',`<span class="period-title">${longMonth(month)}</span>`,'Your monthly plan, brought into focus.',monthSelector()+planSettingsToggle('monthly')+button('+ Add transaction','add-variable','','primary'));
 html+=`<div id="plan-settings-monthly" class="panel monthly-opening-settings" ${state.viewPreferences.hiddenPlanSettings?.monthly?'hidden':''}><div><span>Rollover from ${longMonth(E.addMonths(month+'-01',-1).slice(0,7))}</span><strong class="rollover-amount">${money(m.rollover)}</strong></div><label class="monthly-opening-include"><input type="checkbox" data-monthly-rollover ${m.plan.includeRollover!==false?'checked':''}> Carry over previous month's balance</label><div class="monthly-copy-plan">${button('Copy previous month','copy-previous-plan')}</div></div>`;
 html+=`<div class="metrics metric-four">${metric('Total income',money(m.income),'var(--income)',`Plan ${money(m.groups.Income.expected)}`)}${metric('Total spending',money(m.spending),'var(--plum)',`${percent(m.budgetUsed)} of spending plan`)}${metric('Total saved',money(m.groups.Savings.actual),'var(--teal)','Recorded contributions')}${metric('Available',money(m.balance),m.balance<0?'var(--terra)':'var(--steel)',m.balance<0?'Over budget':'Includes rollover')}</div>`;
 html+=`<div class="grid-two monthly-summary-grid">${panel('Budget summary',`<div class="table-wrap"><table class="monthly-summary-table"><thead><tr><th>Type</th><th class="numeric">Plan</th><th class="numeric">Actual</th><th class="numeric">Used</th></tr></thead><tbody><tr><td>Rollover</td><td class="numeric">${money(m.rollover)}</td><td class="numeric">${money(m.rollover)}</td><td>—</td></tr>${E.TYPES.map(t=>`<tr><td><span class="chip type-chip" style="--category-tone:${typeBadgeColors[t]}">${t}</span></td><td class="numeric">${money(m.groups[t].expected)}</td><td class="numeric">${money(m.groups[t].actual)}</td><td class="numeric ${m.groups[t].actual>m.groups[t].expected?(t==='Income'?'positive':'negative'):''}">${percent(m.groups[t].expected?m.groups[t].actual/m.groups[t].expected:null)}</td></tr>`).join('')}</tbody><tfoot><tr><td>Leftover</td><td class="numeric">${money(m.expectedBalance)}</td><td class="numeric">${money(m.balance)}</td><td></td></tr></tfoot></table></div>`)}${panel('Daily balance',`<div class="panel-body monthly-daily-chart">${lineChart(days.map(d=>d.date.slice(-2)),[{name:'Balance',color:colors.Income,values:days.map(d=>d.balance)}],{width:680,height:280,area:true})}</div>`)}</div>`;
 html+=`<div class="grid-two monthly-spending-row" style="margin-top:22px">${panel('Spending breakdown',`<div class="panel-body monthly-breakdown-body">${donut(spend)}</div>`)}${panel('Budget remaining',`<div class="panel-body budget-remaining-body"><div class="budget-remaining-amount ${m.plannedSpending-m.spending<0?'negative':'positive'}">${money(m.plannedSpending-m.spending)}</div><p class="budget-remaining-caption">${m.plannedSpending===0?'No spending plan set':m.spending>m.plannedSpending?'Over your monthly spending plan':'Left in your monthly spending plan'}</p><div class="budget-remaining-gauge">${semicircleGauge(m.budgetUsed,m.budgetUsed===null?'No spending plan set':percent(m.budgetUsed)+' of spending plan used',m.budgetUsed>1?'terra':'steel')}<p class="budget-gauge-label">Spending plan used</p></div><div class="budget-remaining-totals"><div><span>Planned</span><b>${money(m.plannedSpending)}</b></div><div><span>Spent</span><b>${money(m.spending)}</b></div></div>${m.budgetUsed===null?'<p class="help-text">Enter amounts in Plan below to set your plan.</p>':''}</div>`,'','budget-remaining-panel')}</div>`;
 html+=`<div class="grid-two" style="margin-top:22px">${E.TYPES.map(t=>panel(`<span class="monthly-category-title" data-tone="${categoryTones[t]}">${t}</span>`,`<div class="table-wrap"><table><thead><tr><th>Category</th><th class="numeric" title="Click a Plan amount to edit it.">Plan</th><th class="numeric">Actual</th><th class="numeric">%</th></tr></thead><tbody>${state.categories.filter(c=>c.type===t).map(c=>{const actual=E.sum(m.transactions.filter(x=>x.categoryId===c.id),x=>x.amount),expected=m.plan.categoryPlans[c.id]||0;return `<tr><td>${esc(c.name)}</td><td class="numeric"><button type="button" class="plan-amount-button" data-action="edit-category-plan" data-id="${esc(c.id)}" aria-label="Edit ${esc(c.name)} plan for ${longMonth(month)}" title="Edit plan"><span>${money(expected)}</span><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15z"/></svg></button></td><td class="numeric">${money(actual)}</td><td class="numeric ${actual>expected?(t==='Income'?'positive':'negative'):''}">${percent(expected?actual/expected:null)}</td></tr>`;}).join('')}</tbody></table></div>`)).join('')}</div>`;return html;
}
const expandedFilters=new Set();
function filterToolbar(kind){const keys=['type','account',...(kind!=='recurring'?['month']:[]),...(multipleParticipants()?['person']:[]),...(kind==='payments'?['status']:[])],count=keys.filter(key=>filter[key]!=='All').length,expanded=expandedFilters.has(kind);return `<div class="toolbar compact-filters"><input class="search" id="transaction-search" placeholder="Search category or description…" aria-label="Search transactions" value="${esc(filter.search)}"><button type="button" class="button filters-toggle" data-action="toggle-filters" data-id="${kind}" aria-expanded="${expanded}" aria-controls="transaction-filter-fields">Filters${count?` <span class="filter-count">${count}</span>`:''}<span aria-hidden="true">${expanded?'▴':'▾'}</span></button>${(count||filter.search)?button('Clear','clear-filters','','small'):''}<div id="transaction-filter-fields" class="filter-fields" ${expanded?'':'hidden'}><select data-filter="type" aria-label="Filter type">${options(['All',...E.TYPES],filter.type)}</select>${kind!=='recurring'?`<select data-filter="month" aria-label="Filter month"><option value="All">All months in this year</option>${E.months(state).map(m=>`<option value="${m}" ${filter.month===m?'selected':''}>${longMonth(m)}</option>`).join('')}</select>`:''}<select data-filter="account" aria-label="Filter account"><option value="All">All accounts</option>${options(state.accounts,filter.account)}</select>${multipleParticipants()?`<select data-filter="person" aria-label="Filter person"><option value="All">All people</option>${options(state.people,filter.person)}</select>`:''}${kind==='payments'?`<select data-filter="status" aria-label="Filter payment status">${options(['All','Paid','Upcoming','Overdue'],filter.status)}</select>`:''}</div></div>`;}
function filtered(rows,kind){return rows.filter(r=>(filter.type==='All'||r.type===filter.type)&&(filter.account==='All'||r.accountId===filter.account)&&(!multipleParticipants()||filter.person==='All'||r.personId===filter.person)&&(kind==='recurring'||filter.month==='All'||r.date?.slice(0,7)===filter.month)&&(kind!=='payments'||filter.status==='All'||r.status===filter.status)&&`${catName(r.categoryId)} ${r.description||''} ${r.note||''}`.toLowerCase().includes(filter.search.toLowerCase()));}
function paginated(rows,rowHtml,headers){const pages=Math.max(1,Math.ceil(rows.length/25));filter.page=Math.min(filter.page,pages-1);const visible=rows.slice(filter.page*25,filter.page*25+25);return `<div class="panel table-panel transaction-table-panel" data-tone="${({recurring:'teal',variable:'terra',payments:'plum'})[route]||'plum'}"><div class="panel-head"><h2 class="section-title">${({recurring:'Recurring transactions',variable:'Variable transactions',payments:'Payment schedule'})[route]||'Transactions'}</h2></div>${filterToolbar(route)}<div class="table-wrap"><table><thead><tr>${headers}</tr></thead><tbody>${visible.map(rowHtml).join('')}</tbody></table>${!rows.length?empty('No matching records','Adjust your filters or add a new transaction.'):''}</div><div class="pagination"><span>${rows.length?filter.page*25+1:0}–${Math.min((filter.page+1)*25,rows.length)} of ${rows.length} records</span><span><button class="button small" data-action="page-prev" ${filter.page===0?'disabled':''}>Previous</button> <button class="button small" data-action="page-next" ${filter.page>=pages-1?'disabled':''}>Next</button></span></div></div>`;}
function transactionRow(action,record){return `<tr class="interactive-transaction" tabindex="0" data-row-action="${action}" data-row-id="${esc(record.id)}" aria-label="Edit ${esc(catName(record.categoryId))}">`;}
function transactionMenu(kind,record){const edit=kind==='payments'?'adjust-payment':'edit-'+kind,id='row-menu-'+kind+'-'+record.id;return `<button type="button" class="button small row-menu-trigger" data-action="row-menu" data-id="${esc(id)}" aria-label="Actions for ${esc(catName(record.categoryId))}" aria-haspopup="true" aria-controls="${esc(id)}">⋯</button><div id="${esc(id)}" class="row-actions-popover" popover="auto">${button(kind==='payments'?'Adjust payment':'Edit',edit,record.id,'small')}${kind==='payments'?button(record.paid?'Mark unpaid':'Mark paid',record.paid?'payment-unpaid':'payment-paid',record.id,'small'):button('Delete','delete-'+kind,record.id,'small danger')}</div>`;}
function renderRecurring(){const rows=filtered(state.recurringRules,'recurring');return heading('SET IT UP ONCE','Recurring transactions','Your regular income and payments, scheduled throughout the year.',button('+ Add recurring','add-recurring','','primary'))+paginated(rows,r=>`${transactionRow('edit-recurring',r)}<td><span class="chip type-chip" style="--category-tone:${typeBadgeColors[r.type]}">${r.type}</span></td><td><b>${esc(catName(r.categoryId))}</b>${r.description?`<br><small>${esc(r.description)}</small>`:''}</td><td>${esc(r.frequency)}</td><td class="numeric">${money(r.amount)}</td><td>${niceDate(r.firstDate)}</td><td>${r.lastDate?niceDate(r.lastDate):''}</td><td>${esc(accountName(r.accountId))}</td>${multipleParticipants()?`<td>${esc(personName(r.personId))}</td>`:''}<td>${transactionMenu('recurring',r)}</td></tr>`,`<th>Type</th><th>Category</th><th>Frequency</th><th class="numeric">Amount</th><th>First payment</th><th>Last payment</th><th>Account</th>${multipleParticipants()?'<th>Person</th>':''}<th></th>`);}
function renderPayments(){const all=E.calculatePayments(state).filter(p=>p.date.slice(0,4)===String(state.viewPreferences.reportYear)),rows=filtered(all,'payments'),out=rows.filter(p=>p.type!=='Income'),due=E.sum(out,p=>p.amount),paid=E.sum(out.filter(p=>p.paid),p=>p.amount);return heading('STAY ONE STEP AHEAD','Payment schedule','Check off payments as they happen. Use + Open next year in the year menu to extend your schedule.',button('View calendar','navigate','calendar'))+`<div class="metrics metric-four">${metric('Scheduled outflow',money(due),'var(--steel)','Current filters')}${metric('Paid',money(paid),'var(--teal)','Marked as paid')}${metric('Remaining',money(due-paid),'var(--plum)','Scheduled, unpaid')}${metric('Overdue',money(E.sum(out.filter(p=>p.status==='Overdue'),p=>p.amount)),'var(--terra)','Past due, unpaid')}</div>`+paginated(rows,p=>`${transactionRow('adjust-payment',p)}<td><input type="checkbox" data-paid="${esc(p.id)}" ${p.paid?'checked':''} aria-label="Mark ${esc(catName(p.categoryId))} on ${p.date} as paid"></td><td>${niceDate(p.date)}</td><td><b>${esc(catName(p.categoryId))}</b><br><small>${p.type}${state.paymentOverrides[p.id]&&(state.paymentOverrides[p.id].date!==null&&state.paymentOverrides[p.id].date!==undefined||state.paymentOverrides[p.id].amount!==null&&state.paymentOverrides[p.id].amount!==undefined)?' · Adjusted':''}</small></td><td class="numeric">${money(p.amount)}</td><td><span class="chip ${p.status}">${p.status}</span></td><td>${esc(accountName(p.accountId))}</td>${multipleParticipants()?`<td>${esc(personName(p.personId))}</td>`:''}<td>${esc(p.note)}</td><td>${transactionMenu('payments',p)}</td></tr>`,`<th>Paid</th><th>Date</th><th>Category</th><th class="numeric">Amount</th><th>Status</th><th>Account</th>${multipleParticipants()?'<th>Person</th>':''}<th>Note</th><th></th>`);}
function renderVariable(){const rows=filtered(state.variableTransactions.filter(t=>t.date.slice(0,4)===String(state.viewPreferences.reportYear)).sort((a,b)=>b.date.localeCompare(a.date)),'variable');return heading('THE EVERYDAY DETAILS','Variable transactions','One-off spending, extra income, and everything in between.',button('+ Add transaction','add-variable','','primary'))+paginated(rows,t=>`${transactionRow('edit-variable',t)}<td>${niceDate(t.date)}</td><td><span class="chip type-chip" style="--category-tone:${typeBadgeColors[t.type]}">${t.type}</span></td><td><b>${esc(catName(t.categoryId))}</b></td><td class="numeric">${money(t.amount)}</td><td>${esc(accountName(t.accountId))}</td>${multipleParticipants()?`<td>${esc(personName(t.personId))}</td>`:''}<td>${esc(t.description)}</td><td>${transactionMenu('variable',t)}</td></tr>`,`<th>Date</th><th>Type</th><th>Category</th><th class="numeric">Amount</th><th>Account</th>${multipleParticipants()?'<th>Person</th>':''}<th>Description</th><th></th>`);}
function renderCalendar(){const month=currentMonth(),payments=E.calculatePayments(state).filter(p=>p.date.slice(0,7)===month),out=payments.filter(p=>p.type!=='Income'),due=E.sum(out,p=>p.amount),paid=E.sum(out.filter(p=>p.paid),p=>p.amount),overdue=E.sum(out.filter(p=>p.status==='Overdue'),p=>p.amount),first=new Date(month+'-01T12:00:00Z'),monday=state.settings.weekStartsOn==='Monday',offset=(first.getUTCDay()+(monday?6:0))%7,last=Number(E.addDays(E.addMonths(month+'-01',1),-1).slice(-2)),daynames=monday?['Mon','Tue','Wed','Thu','Fri','Sat','Sun']:['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];let html=heading('A CLEARER MONTH AHEAD','Bill calendar','Scheduled recurring payments, including income.',monthSelector()+`<select id="week-start" aria-label="First day of week">${options(['Monday','Sunday'],state.settings.weekStartsOn)}</select>`)+`<div class="metrics metric-four">${metric('Total due',money(due),'var(--steel)','Due this month')}${metric('Paid',money(paid),'var(--teal)',`${percent(due?paid/due:0)} of scheduled outflow`)}${metric('Remaining',money(due-paid),'var(--plum)','Still to pay')}${metric('Overdue',money(overdue),'var(--terra)','Past due date')}</div><div class="calendar-grid" style="--calendar-weeks:${Math.ceil((offset+last)/7)}">${daynames.map(d=>`<div class="weekday">${d.toUpperCase()}</div>`).join('')}`;const weeks=[];for(let i=0;i<Math.ceil((offset+last)/7)*7;i++){const day=i-offset+1;if(day<1||day>last){html+='<div class="calendar-day blank"></div>';continue;}const date=`${month}-${String(day).padStart(2,'0')}`,ps=payments.filter(p=>p.date===date),income=ps.filter(p=>p.type==='Income');weeks[Math.floor(i/7)]=(weeks[Math.floor(i/7)]||0)+E.sum(ps.filter(p=>p.type!=='Income'),p=>p.amount);html+=`<div class="calendar-day ${date===E.today()?'today':''}"><div class="calendar-date-header">${income.length?`<button class="payday-date" data-action="calendar-payday" data-id="${date}" aria-label="${date}: Payday, ${income.length} income payments"><span class="day-number">${day}</span><span>Payday</span></button>`:`<span class="day-number">${day}</span>`}</div>${ps.filter(p=>p.type!=='Income').map(p=>`<button data-type="${p.type}" class="event ${p.paid?'is-paid':''} ${p.type==='Income'?'Paid':p.status}" data-action="adjust-payment" data-id="${esc(p.id)}"><b>${p.type==='Income'?'+ ':p.paid?'✓ ':''}${esc(catName(p.categoryId))}</b>${money(p.amount)} · ${p.status}</button>`).join('')}</div>`;}return html+'</div>';}
function renderAccounts(){const rows=E.calculateAccountBalances(state);return heading('WHERE YOUR MONEY LIVES','Accounts','Reconcile your accounts with opening balances and adjustments.',button('+ Add account','add-account','','primary'))+`<div class="metrics metric-four">${metric('Current balance',money(E.sum(rows,a=>a.currentBalance)),'var(--steel)','Across all accounts')}${metric('Total deposits',money(E.sum(rows,a=>a.deposits)),'var(--teal)','Recorded income')}${metric('Total withdrawals',money(E.sum(rows,a=>a.withdrawals)),'var(--terra)','Non-income transactions')}${metric('Accounts',rows.length,'var(--plum)','All accounts')}</div>`+panel('Account balances',`<div class="table-wrap"><table><thead><tr><th>Account</th><th class="numeric">Opening</th><th class="numeric">Deposits</th><th class="numeric">Withdrawals</th><th class="numeric">Adjustment</th><th class="numeric">Current</th><th>Last checked</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td><b>${esc(a.name)}</b></td><td class="numeric">${money(a.openingBalance)}</td><td class="numeric positive">${money(a.deposits)}</td><td class="numeric">${money(a.withdrawals)}</td><td class="numeric">${money(a.adjustment)}</td><td class="numeric ${a.currentBalance<0?'negative':''}"><b>${money(a.currentBalance)}</b></td><td>${niceDate(a.lastChecked)}</td><td>${button('Edit','edit-account',a.id,'small')}</td></tr>`).join('')}</tbody></table></div>`); }

function renderSavings(){const goals=E.calculateSavingsProgress(state);return heading('MAKE SPACE FOR YOUR GOALS','Savings','Track what you have saved and the pace of your original plan.',button('+ Add goal','settings-plan','savings','primary'))+`<div class="metrics metric-four">${metric('Current saved',money(E.sum(goals,g=>g.saved)),'var(--teal)','Opening + contributions')}${metric('Savings goals',money(E.sum(goals,g=>g.goalAmount)),'var(--steel)','Combined targets')}${metric('Left to save',money(E.sum(goals,g=>g.remaining)),'var(--plum)','Remaining to save')}${metric('Monthly plan',money(E.sum(goals,g=>g.saveMonthly)),'var(--teal)','From original start dates')}</div><div class="grid-three savings-goal-cards">${goals.map((g,i)=>panel(esc(catName(g.categoryId)),`<div class="panel-body"><div class="goal-value positive">${money(g.saved)}</div><small>of ${money(g.goalAmount)} goal</small><div class="progress"><span style="width:${Math.max(0,Math.min(100,(g.progress||0)*100))}%"></span></div><div class="label-row"><span>Progress</span><b>${percent(g.progress)}</b></div><div class="label-row"><span>Remaining</span><span>${money(g.remaining)}</span></div><div class="label-row"><span>Save monthly</span><span>${money(g.saveMonthly)}</span></div><div class="label-row"><span>Target date</span><span>${niceDate(g.targetDate)}</span></div><div class="label-row"><span>Months left</span><span>${g.monthsLeft??'—'}</span></div></div>`,button('Edit','edit-goal',g.id,'small'),`item-card item-${['teal','steel','plum','terra'][i%4]}`)).join('')}</div><p class="help-text">Monthly plan = (goal − starting amount) ÷ original saving period. Contributions update progress, while your original monthly target stays the same.</p>`;}
function planSettingsToggle(section){const hidden=!!state.viewPreferences.hiddenPlanSettings?.[section];return `<div class="plan-settings-toggle"><button type="button" class="button" data-action="toggle-plan-settings" data-id="${section}" aria-controls="plan-settings-${section}" aria-expanded="${!hidden}">${hidden?'Show settings':'Hide settings'}</button></div>`;}
function debtProgressChart(d){
 const month=E.today().slice(0,7),start=state.debtPlan.startDate.slice(0,7);
 const balance=d.currentBalance??(month<start?d.total:d.payoffDate&&month>d.payoffDate.slice(0,7)?0:null);
 const progress=d.total>0&&balance!==null?Math.max(0,Math.min(1,1-balance/d.total)):null;
 const value=progress===null?'—':Math.round(progress*100)+'%';
 return panel('Debt payoff progress',`<div class="panel-body debt-progress-chart">${donut([{name:'Projected reduction',value:progress??0,color:'#6A9E96'},{name:'Remaining',value:1-(progress??0),color:'#D4E8E4'}],'',value,{separators:false})}</div>`,'','debt-progress-panel');
}
function renderDebt(){const scheduleMoney=n=>n===0?'—':money(n),p=state.debtPlan,d=E.calculateDebtPayoff(state),shown=d.rows,current=d.rows.find(r=>r.date.slice(0,7)===E.today().slice(0,7));return heading('ONE PAYMENT AT A TIME','Debt payoff','Past payments and your repayment plan.',planSettingsToggle('debt')+button('+ Add debt','settings-plan','debt','primary'))+`<div id="plan-settings-debt" class="panel debt-inline-settings" ${state.viewPreferences.hiddenPlanSettings?.debt?'hidden':''}><label>Repayment start date<input type="date" id="debt-start-date" value="${esc(p.startDate)}" min="1900-01-01" max="2200-12-31" required></label><label>Extra monthly payment<input type="number" id="debt-extra-payment" value="${Number(p.extraMonthlyPayment).toFixed(2)}" min="0" step="0.01" required></label><label title="Snowball: smallest balance first. Avalanche: highest interest first. Custom: your priority order.">Strategy<select id="debt-strategy" aria-label="Debt repayment strategy">${options(['Snowball','Avalanche','Custom'],p.strategy)}</select></label><label class="debt-actual-toggle"><input id="debt-use-actual" type="checkbox" ${p.useActualPayments!==false?'checked':''}>Use actual payments for past months</label><p class="debt-actual-note help-text">${p.useActualPayments!==false?'Completed months use recorded Debt payments. Current and future months are projected. Interest and balances are estimated. No recorded payment means zero paid.':'All months follow your repayment plan.'}</p></div><div class="metrics metric-four">${metric('Starting debt',money(d.total),'var(--terra)',`${d.debts.length} debts in your plan`)}${metric('Projected balance',money(d.currentBalance),'var(--steel)','At month end')}${metric('Debt-free date',d.payoffDate?niceDate(d.payoffDate):'Not reached','var(--teal)',d.payoffDate?p.strategy+' strategy':'Not repaid within 372 months')}${metric('Total interest',money(d.interest),'var(--plum)','Across the projection')}</div>`+`<div class="debt-overview-charts">${debtProgressChart(d)}`+panel('Debt balance over time',`<div class="panel-body debt-balance-chart">${d.rows.length?lineChart(shown.map(r=>`${shortMonth(r.date.slice(0,7))}`),[{name:'Projected debt',color:colors.Debt,values:shown.map(r=>r.balance)}],{area:true,height:260,width:760,debtTimeline:true}):empty('Add your first debt','Enter a starting balance, minimum payment and interest rate.')}</div>`)+`</div><div class="grid-three debt-schedule-cards" style="margin-top:22px">${d.debts.map((debt,i)=>{const balanceRow=current||(E.today().slice(0,7)>=p.startDate.slice(0,7)?d.rows.at(-1):null),now=balanceRow?.detail.find(x=>x.id===debt.id),last=d.rows.find(r=>r.detail.find(x=>x.id===debt.id).balance<1e-8);return panel(esc(catName(debt.categoryId)),`<div class="panel-body"><div class="goal-value">${money(now?.balance??debt.startingBalance)}</div><div class="label-row"><span>Starting balance</span><span>${money(debt.startingBalance)}</span></div><div class="label-row"><span>Minimum payment</span><span>${money(debt.minimumPayment)}</span></div><div class="label-row"><span>Annual interest</span><span>${percent(debt.annualRate)}</span></div><div class="label-row"><span>Payoff date</span><span>${last?niceDate(last.date):'Not reached'}</span></div><div class="progress"><span style="width:${Math.max(0,Math.min(100,(1-(now?.balance??debt.startingBalance)/debt.startingBalance)*100))}%"></span></div></div><div class="table-wrap debt-card-schedule" tabindex="0" role="region" aria-label="${esc(catName(debt.categoryId))} payment schedule"><table><thead><tr><th>Month</th><th>Payment</th><th>Balance</th></tr></thead><tbody>${d.rows.map(r=>{const entry=r.detail.find(x=>x.id===debt.id);return `<tr class="${r.date.slice(0,7)===E.today().slice(0,7)?'current-payment-month':''}"><td>${shortMonth(r.date.slice(0,7))}<small class="debt-row-source">${r.isActual?'Actual':'Projected'}</small></td><td class="numeric">${scheduleMoney(entry.payment)}</td><td class="numeric">${scheduleMoney(entry.balance)}</td></tr>`;}).join('')}</tbody><tfoot><tr><td>Total</td><td class="numeric">${scheduleMoney(E.sum(d.rows,r=>r.detail.find(x=>x.id===debt.id).payment))}</td><td class="numeric">${scheduleMoney(d.rows.at(-1)?.detail.find(x=>x.id===debt.id).balance??0)}</td></tr></tfoot></table></div>`,button('Edit','edit-debt',debt.id,'small'),`item-card item-${['teal','steel','plum','terra'][i%4]}`);}).join('')}</div><div style="margin-top:22px">${panel('Monthly repayment schedule',`<div class="table-wrap" style="max-height:520px"><table><thead><tr><th>Month</th><th class="numeric">Extra adjustment</th><th class="numeric">Payment</th><th class="numeric">Interest</th><th class="numeric">Balance</th><th></th></tr></thead><tbody>${d.rows.map(r=>`<tr><td>${shortMonth(r.date.slice(0,7))}<small class="debt-row-source">${r.isActual?'Actual':'Projected'}</small></td><td class="numeric">${r.isActual?'—':`<input class="inline-number" type="number" step="0.01" min="${-p.extraMonthlyPayment}" value="${r.adjustment===0?'':Number(r.adjustment).toFixed(2)}" placeholder="—" data-debt-adjustment="${r.date.slice(0,7)}" aria-label="Extra payment adjustment ${r.date.slice(0,7)}">`}</td><td class="numeric">${scheduleMoney(r.payment)}</td><td class="numeric">${scheduleMoney(r.interest)}</td><td class="numeric">${scheduleMoney(r.balance)}</td><td>${button('Details','debt-month',r.date,'small')}</td></tr>`).join('')||'<tr><td colspan="6">Add a debt to see projected monthly payments.</td></tr>'}</tbody></table></div>`)}</div><p class="help-text">Interest is applied after each payment, at annual rate ÷ 12, matching the workbook. Extra adjustments add to the monthly extra payment.</p>`;}
function renderAllocation(){const a=E.calculate503020(state),rowCount=Math.max(0,...a.groups.map(g=>g.categories.length)),parts=a.groups.map((g,i)=>({name:g.name,value:g.actual,color:[colors.Bills,colors.Expenses,colors.Savings][i]}));return heading('FIND YOUR BALANCE','50/30/20 budget','Compare your spending mix for '+longMonth(currentMonth())+'.',monthSelector()+planSettingsToggle('allocation'))+`<div id="plan-settings-allocation" class="panel allocation-inline-settings" ${state.viewPreferences.hiddenPlanSettings?.allocation?'hidden':''}>${['Needs','Wants','Debt & Savings'].map((group,i)=>`<label>${group} (%)<input type="number" id="allocation-share-${i}" data-allocation-share="${i}" value="${Math.round(state.allocationPlan.shares[group]*1000000)/10000}" min="0" max="100" step="any" required></label>`).join('')}<p id="allocation-share-status" class="help-text" role="status">Total: 100%. Changes save when the shares total 100%.</p></div><div class="metrics metric-four">${metric('Allocated spending',money(a.total),'var(--steel)',longMonth(currentMonth()))}${a.groups.map((g,i)=>metric(g.name,money(g.actual),['var(--steel)','var(--plum)','var(--teal)'][i],`${percent(g.actualShare)} actual · ${percent(g.share)} plan`)).join('')}</div><div class="grid-two">${panel('Budget summary',`<div class="panel-body allocation-budget-chart">${legend([{name:'Plan',color:colors.Expenses},{name:'Actual',color:colors.Bills}])}${barChart(a.groups.map(g=>g.name),[{name:'Plan',color:colors.Expenses,values:a.groups.map(g=>g.expected)},{name:'Actual',color:colors.Bills,values:a.groups.map(g=>g.actual)}],{width:680,height:260})}</div>`)}${panel('Spending breakdown',`<div class="panel-body allocation-spending-chart">${donut(parts)}</div>`)}</div><div class="grid-three allocation-tables" style="margin-top:22px">${a.groups.map(g=>panel(g.name,`<div class="table-wrap"><table class="allocation-table"><colgroup><col style="width:50%"><col style="width:30%"><col style="width:20%"></colgroup><thead><tr><th>Category</th><th class="numeric">Actual</th><th class="numeric">Share</th></tr></thead><tbody>${g.categories.map(c=>`<tr><td>${esc(c.name)}</td><td class="numeric">${money(c.actual)}</td><td class="numeric">${percent(g.actual?c.actual/g.actual:0)}</td></tr>`).join('')}${Array.from({length:rowCount-g.categories.length},()=>'<tr class="allocation-empty-row" aria-hidden="true"><td></td><td></td><td></td></tr>').join('')}</tbody><tfoot><tr><td>Total</td><td class="numeric">${money(g.actual)}</td><td class="numeric">${g.actual?'100%':'—'}</td></tr></tfoot></table></div>`)).join('')}</div>`;}
function semicircleGauge(ratio,label,tone='steel'){
 const filled=ratio===null?0:Math.max(0,Math.min(1,ratio))*100;
 return `<svg class="networth-goal-gauge" viewBox="0 0 280 164" role="img" aria-label="${esc(label)}"><path class="goal-gauge-track" d="M20 140 A120 120 0 0 1 260 140" fill="none" stroke-width="24" stroke-linecap="round"/>${filled>0?`<path class="goal-gauge-fill" style="stroke:var(--${tone})" d="M20 140 A120 120 0 0 1 260 140" pathLength="100" fill="none" stroke-width="24" stroke-linecap="round" stroke-dasharray="${filled} 100"/>`:''}<text x="140" y="128" text-anchor="middle" style="fill:var(--${tone})">${percent(ratio)}</text></svg>`;
}
function netWorthGoalGauge(n){
 const ratio=n.goal>0?n.netWorth/n.goal:null;
 return `<div class="panel-body networth-goal-progress networth-goal-semicircle">${semicircleGauge(ratio,ratio===null?'Set a net worth goal':percent(ratio)+' of net worth goal')}<div class="networth-gauge-caption"><strong>${money(n.netWorth)}</strong><span>${n.goal>0?'of '+money(n.goal):'Set your goal above'}</span></div></div>`;
}
function renderNetWorth(){const n=E.calculateNetWorth(state),ms=E.months(state);return heading('YOUR FINANCIAL PICTURE','Net worth','Your monthly assets, liabilities and net worth.',planSettingsToggle('networth')+button('+ Add item','add-networth','','primary'))+`<div id="plan-settings-networth" class="panel networth-inline-settings" ${state.viewPreferences.hiddenPlanSettings?.networth?'hidden':''}><label>Net worth goal<input type="number" id="networth-goal-amount" value="${Number(state.netWorth.goal).toFixed(2)}" min="0" step="0.01" required></label></div><div class="metrics">${metric('Net worth goal',money(n.goal),'var(--plum)','Your long-term target')}${metric('Total assets',money(n.assets),'var(--teal)',n.assetsMonth?longMonth(n.assetsMonth):'No balances entered')}${metric('Total liabilities',money(n.liabilities),'var(--terra)',n.liabilitiesMonth?longMonth(n.liabilitiesMonth):'No balances entered')}${metric('Net worth',money(n.netWorth),'var(--steel)',`${percent(n.goal?n.netWorth/n.goal:null)} of goal`)}${metric('Left to goal',money(n.remaining),'var(--plum)','Goal minus net worth')}</div>`+`<div class="networth-charts-row">`+panel('Progress towards goal',netWorthGoalGauge(n))+`${panel('Assets vs liabilities by month',`<div class="panel-body networth-monthly-chart">${legend([{name:'Assets',color:colors.Income},{name:'Liabilities',color:colors.Debt}])}${barChart(ms.map(shortMonth),[{name:'Assets',color:colors.Income,values:n.rows.map(r=>r.assets)},{name:'Liabilities',color:colors.Debt,values:n.rows.map(r=>r.liabilities)}],{height:220,width:960})}</div>`)}${panel('Assets breakdown',`<div class="panel-body networth-assets-chart">${donut(['Cash & Bank Accounts','Investments','Property','Other Assets'].map((group,i)=>{const rows=ms.map(m=>E.sum(n.items.filter(x=>x.side==='asset'&&x.group===group),x=>x.balances[m]));return {name:group,value:rows[ms.indexOf(n.assetsMonth)]||0,color:[colors.Income,colors.Bills,colors.Expenses,colors.Debt][i]};}),'ASSETS')}</div>`)}</div>`+`<div style="margin-top:22px">${panel('Net worth',`<div class="table-wrap"><table class="networth-monthly-summary"><thead><tr><th></th>${ms.map(m=>`<th>${shortMonth(m)}</th>`).join('')}</tr></thead><tbody><tr><td>Total assets</td>${n.rows.map(r=>`<td>${money(r.assets)}</td>`).join('')}</tr><tr><td>Total liabilities</td>${n.rows.map(r=>`<td>${money(r.liabilities)}</td>`).join('')}</tr></tbody><tfoot><tr><td>Net worth</td>${n.rows.map(r=>`<td>${money(r.netWorth)}</td>`).join('')}</tr></tfoot></table></div>`)}</div>`+['asset','liability'].map(side=>`<div style="margin-top:22px">${panel(side==='asset'?'Assets':'Liabilities',`<div class="table-wrap"><table><thead><tr><th>Item</th>${ms.map(m=>`<th class="numeric">${shortMonth(m)}</th>`).join('')}<th class="numeric">Growth</th><th></th></tr></thead><tbody>${state.netWorth.items.filter(i=>i.side===side).map(i=>{const resolved=n.items.find(x=>x.id===i.id),values=ms.map(m=>resolved.balances[m]).filter(v=>v!==null&&v!==undefined);return `<tr><td><b>${esc(resolved.name)}</b><br><small>${esc(i.group)}</small></td>${ms.map(m=>`<td><button type="button" class="plan-amount-button networth-amount-button" data-action="edit-networth-balance" data-id="${esc(i.id)}|${m}" aria-label="Edit ${esc(i.name)} balance for ${longMonth(m)}" title="Edit balance"><span>${money(i.balances[m])}</span><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15z"/></svg></button></td>`).join('')}<td class="numeric">${values.length?money(values.at(-1)-values[0]):'—'}</td><td>${button('Edit','edit-networth',i.id,'small')}</td></tr>`;}).join('')}</tbody><tfoot><tr><td>Total</td>${n.rows.map(r=>`<td class="numeric">${money(side==='asset'?r.assets:r.liabilities)}</td>`).join('')}<td></td><td></td></tr></tfoot></table></div>`)}</div>`).join('');}
const budgetCurrencies=[['USD','US Dollar','$'],['EUR','Euro','€'],['GBP','British Pound','£'],['CAD','Canadian Dollar','CA$'],['AUD','Australian Dollar','A$'],['NZD','New Zealand Dollar','NZ$'],['CHF','Swiss Franc','CHF'],['JPY','Japanese Yen','¥'],['CNY','Chinese Yuan','CN¥'],['INR','Indian Rupee','₹'],['RUB','Russian Ruble','₽'],['UAH','Ukrainian Hryvnia','₴'],['PLN','Polish Zloty','zł'],['SEK','Swedish Krona','SEK'],['NOK','Norwegian Krone','NOK'],['DKK','Danish Krone','DKK'],['BRL','Brazilian Real','R$'],['MXN','Mexican Peso','MX$'],['AED','UAE Dirham','AED']];
function budgetPreferenceFields(){
 const s=state.settings,currency=s.currencyCode||budgetCurrencies.find(c=>c[2]===s.currencySymbol)?.[0]||'custom';
 const field=(label,key,control)=>`<label class="budget-preference-field"><span>${label}</span>${control}</label>`;
 const select=(key,list,value)=>`<select data-budget-setting="${key}">${options(list,value)}</select>`;
 return `<div class="panel-body"><div class="budget-preference-fields">`+
 field('Budget name','budgetName',`<input data-budget-setting="budgetName" value="${esc(s.budgetName||'My household')}" maxlength="80" required>`)+
 field('Currency','currencyCode',select('currencyCode',[...budgetCurrencies.map(c=>({id:c[0],name:c[0]+' — '+c[1]})),{id:'custom',name:'Custom'}],currency))+
 (currency==='custom'?field('Custom currency symbol','currencySymbol',`<input data-budget-setting="currencySymbol" value="${esc(s.currencySymbol)}" maxlength="8" required>`):'')+
 field('Currency position','currencyPosition',select('currencyPosition',[{id:'before',name:'Before amount'},{id:'after',name:'After amount'}],s.currencyPosition||'before'))+
 field('Week starts on','weekStartsOn',select('weekStartsOn',['Monday','Sunday'],s.weekStartsOn))+
 `</div></div>`;
}
function renderSetup(){
 let content='';
  content+=`<div class="settings-top-grid">${panel('Budget preferences',budgetPreferenceFields())}${panel('Participants',`<div class="panel-body"><fieldset class="participant-choice"><legend>Who is this budget for?</legend><label><input type="radio" name="participant-mode" value="single" ${!multipleParticipants()?'checked':''}><span>One</span></label><label><input type="radio" name="participant-mode" value="multiple" ${multipleParticipants()?'checked':''}><span>Multiple</span></label></fieldset>${multipleParticipants()?state.people.map(p=>`<div class="label-row"><span>${esc(p.name)}</span>${button('Edit','edit-person',p.id,'small')}</div>`).join(''):`<div class="single-participant-row"><label class="single-participant-label">Budget participant<select id="primary-participant">${options(state.people,primaryParticipant())}</select></label>${primaryParticipant()?button('Edit','edit-person',primaryParticipant(),'small'):''}</div>`}${multipleParticipants()||!state.people.length?button('+ Add participant','add-person','','small'):''}</div>`)}`;
  content+=panel('Accounts',`<div class="panel-body settings-compact-accounts"><div class="settings-category-list">${state.accounts.map(a=>`<div class="settings-category-row"><div><b>${esc(a.name)}</b><small>${esc(a.type||'Bank')}</small></div>${button('Edit','edit-account',a.id,'small')}</div>`).join('')}</div></div>`,button('+ Add account','add-account','','small settings-add-account'));
  content+='</div>';
  content+=`<div class="settings-category-grid">${E.TYPES.map(type=>panel(type,`<div class="panel-body" id="settings-category-${type.toLowerCase()}"><div class="settings-category-list">${state.categories.filter(c=>c.type===type).map(c=>`<div class="settings-category-row"><div><b>${esc(c.name)}</b>${type!=='Income'?`<small>${esc(c.budgetGroup||'Not allocated')}</small>`:''}</div>${button('Edit','edit-category',c.id,'small')}</div>`).join('')}</div><div class="settings-category-add">${button('+ Add category','add-category-type',type,'small')}</div></div>`,'','settings-category-card')).join('')}</div>`;
  content+=panel('Start fresh',`<div class="panel-body"><p class="explain">Restore demo data or begin with empty transactions and balances.</p><div class="heading-actions">${button('Reset demo','reset-demo','','danger')}${button('Clear budget','clear-budget','','danger')}</div></div>`,'','danger-zone');
 return heading('MAKE IT YOURS','Settings','Set up your budget, accounts and categories.')+`<div class="settings-single-page">${content}</div>`;
}

function renderHelp(){const sections=[["Start here", "<p>Welcome to your ULTIMATE BUDGET. Set up your budget once, record your transactions, and use the dashboards to see your progress.</p><ol><li>Open Settings and choose your currency, participants and accounts.</li><li>Review participants, accounts and categories.</li><li>Add regular income and payments in Recurring transactions.</li><li>Mark completed payments in Payment schedule. Add one off activity in Variable transactions.</li><li>Enter your Plan amounts in Monthly budget.</li><li>Check Annual overview and export a backup regularly.</li></ol><p>Edit fields and use the Add or Edit buttons. Calculated totals and charts update automatically. Unlike the spreadsheet, there are no cells or formulas to manage.</p><h3 class=\"guide-example-title\">Try this example</h3><p>Start with one account and one income source. Add a monthly bill, mark its occurrence Paid, and check that both entries appear in the correct month before entering the rest of your budget.</p>"], ["Settings: budget preferences and participants", "<p><b>Budget preferences:</b> give your budget a name, select a currency and its position, and choose the first day of the week. There are no start month or start year fields in Settings. Choose Custom at the end of the currency list to enter your own symbol. Changing currency changes the display; it does not convert amounts.</p><p>Keep multiple years in the same budget. Choose a year at the top of Annual overview or another dated report. Each year runs from January through December. Switching years only changes the view: all transactions, monthly plans and Net worth snapshots retain their dates. New months have empty plans until you enter amounts. Recurring schedules continue according to their first and last dates.</p><p><b>Participants:</b> choose One participant to hide person fields in transaction forms, filters and tables. Choose Multiple participants to assign activity to different people. Switching to one participant keeps existing assignments.</p><p>Preferences save when you change a selection or leave an edited field. Forms with a Save changes button save when you submit them.</p><h3 class=\"guide-example-title\">Try this example</h3><p>Record your first transaction or recurring schedule to begin. Its date determines the initial month and year. Report menus list available years. Monthly budget offers + Add month, and Payment schedule offers + Open next year. Switching periods does not move your records. Choose Multiple participants if you need a person selection in transaction forms.</p>"], ["Settings: accounts and categories", "<p><b>Accounts:</b> enter the name, type and opening balance for each account. Available types are Cash, Bank, Savings, Credit card and Investment. Use Add account for another row. Opening balance is the amount before the transactions you will record; do not also log it as income.</p><p><b>Categories:</b> organise your entries under Income, Bills, Expenses, Debt and Savings. Use Add category or Edit. Renaming a category keeps its existing transactions and plans connected. An existing category\u2019s transaction type stays fixed.</p><p>For each non income category, choose Needs, Wants or Debt &amp; Savings. This assignment controls where it appears in 50/30/20. Category lists become the choices in transaction forms.</p><p>Account types and transaction types are different: a Savings account is a place where money is held; a Savings transaction is a recorded contribution.</p><h3 class=\"guide-example-title\">Try this example</h3><p>Add your everyday account with a $1,000 opening balance. Add Rent under Bills and assign Needs as its budget group. You can now choose both the account and Rent when entering a recurring payment. The opening balance belongs in the account setup, not in an Income transaction.</p>"], ["Recurring transactions: regular income and payments", "<p>Use Add recurring for anything that repeats. Enter one rule per item:</p><ul><li><b>Type and category:</b> what the payment belongs to.</li><li><b>Frequency and amount:</b> how often it repeats and the amount of one occurrence.</li><li><b>First payment:</b> the date from which the schedule starts.</li><li><b>Last payment:</b> optional. Leave it blank if there is no end date; payments are generated within the selected year. An entered end date is inclusive.</li><li><b>Account and person:</b> where the money moves and who it belongs to. Person appears only in multiple participant mode.</li></ul><p>Weekly schedules repeat every 7, 14 or 28 days. Monthly schedules repeat every 1, 2, 3, 6 or 12 calendar months. A date such as the 31st moves to the last available day in shorter months, then returns to the original day when possible.</p><p>For two fixed paydays each month, add two Every Month rules. This is different from Every 2 Weeks.</p><p>A recurring rule creates a schedule, not actual income or spending. Mark each occurrence as Paid when completed.</p><h3 class=\"guide-example-title\">Try this example</h3><p>Choose Bills, then Rent. Enter $1,200, choose Every Month, set First payment to August 1, 2026, and select the account. Leave Last payment blank if it continues. Save, then open Payment schedule to see each occurrence. None of these occurrences counts as paid spending until you mark it Paid.</p>"], ["Payment schedule: paid status and adjustments", "<p>Recurring rules appear here as individual dated payments. Use filters to narrow the list. The top totals follow the selected filters and exclude Income.</p><ul><li><b>Paid:</b> tick completed payments, including income you have received.</li><li><b>Upcoming:</b> not marked Paid and due today or later.</li><li><b>Overdue:</b> before today and still unpaid.</li></ul><p>Only Paid recurring payments enter actual totals. Marking a future dated occurrence Paid includes it in its effective month, even before that date arrives.</p><p>Use Adjust to change one occurrence\u2019s date, amount, account or person and add a note. Leave an adjustment blank to use the original value. Zero is a valid replacement amount. Moving the date also moves the payment to the corresponding month in the dashboards.</p><p>Editing a recurring rule preserves recorded payments when you choose Keep recorded payments. Changing its dates or frequency also offers Rebuild payments through today; that choice rebuilds the selected rule and marks scheduled occurrences through today as paid. Do not also enter the same payment in Variable transactions: that would count it twice.</p><h3 class=\"guide-example-title\">Try this example</h3><p>If September rent was $1,250 and paid on September 3, open that occurrence and choose Adjust. Enter the new amount and date, keep unchanged fields blank, and mark it Paid. October keeps its original amount and date. Untick Paid if you marked an occurrence by mistake.</p>"], ["Variable transactions: one off activity", "<p>Use Add transaction for purchases, irregular income and other activity that does not need a repeating schedule. Enter the date, type, category, amount and account. Add a person when enabled and an optional description.</p><p>Variable transactions count as actual immediately; there is no separate Paid checkbox. The date determines their month. They feed Monthly budget, Annual overview, Accounts and 50/30/20, and relevant categories feed Savings and No spend tracker.</p><p>For a refund that should reduce spending in a category, enter a negative amount in that same spending category. Recording it as Income instead increases income and does not reduce the original category\u2019s spending.</p><p>Use search and filters to find an entry, then Edit to correct it.</p><h3 class=\"guide-example-title\">Try this example</h3><p>Choose Add transaction, enter September 5, select Expenses and Groceries, enter $65, and choose the account used. Save changes. September groceries and the account withdrawals increase by $65. Use Edit on this entry if you made a mistake; do not create a second entry to replace it.</p>"], ["Monthly budget: plans, actuals and balance", "<p>Open the month/year picker at the top. Choose an available month or use + Add month. Click a Plan amount in the category tables to edit planned income or outgoings in a dialog, then click Save changes. Actual and Used update from Paid recurring payments and variable transactions.</p><p><b>Show settings</b> shows Rollover from the previous month and an option to include it. The amount updates automatically from recorded transactions, including negative balances.</p><ul><li><b>Total income:</b> actual Income for the month.</li><li><b>Total spending:</b> Bills + Expenses + Debt + Savings. Savings contributions therefore count as an outflow here.</li><li><b>Total saved:</b> Savings contributions recorded during this month, excluding starting savings balances.</li><li><b>Available to spend:</b> income minus all spending, plus rollover if enabled. A negative amount means spending exceeds income and rollover; it does not necessarily mean your spending plan was exceeded.</li></ul><p><b>Budget summary</b> compares Plan and Actual for each type. Used is Actual \u00f7 Plan. With no plan, the percentage is unavailable.</p><p><b>Budget remaining</b> shows planned spending minus actual spending. Its semicircle shows the proportion of the spending plan used. It is separate from Available to spend, which depends on income.</p><p><b>Daily balance</b> follows income and outgoings by day, including rollover from the previous month. <b>Spending breakdown</b> shows how outflows divide between Bills, Expenses, Debt and Savings.</p><h3 class=\"guide-example-title\">Try this example</h3><p>If the monthly spending plan is $2,000 and actual outflow is $1,500, Budget remaining is $500 and the gauge shows 75% used. If income is $2,500, Available to spend is $1,000 before rollover. These cards differ because one compares spending with your plan and the other compares it with your income.</p><p>Copy previous month opens a preview of the previous calendar month\u2019s category plans. Save changes replaces this month\u2019s category plans without changing transactions or rollover settings. Disabling rollover starts a new chain from this month.</p>"], ["Annual overview: your selected year", "<p>Choose a year at the top. This dashboard summarises January through December of that year. Enter transactions and plans in their own sections; there is nothing to enter into the annual charts or summary tables.</p><ul><li><b>Income &amp; spending:</b> monthly income compared with all outflows.</li><li><b>Spending breakdown:</b> annual Bills, Expenses, Debt and Savings.</li><li><b>Budget vs actual:</b> planned leftover compared with actual leftover for each month, not planned versus actual spending.</li><li><b>Running balance:</b> cumulative income minus outflows. Monthly rollover is not added again to this chart.</li><li><b>Cash flow summary:</b> monthly income, outflow types and leftover, with annual totals. Annual leftover shows monthly cash flow without counting rollover again.</li><li><b>Monthly overview:</b> choose a transaction type to see its total and monthly amounts. Months stay in chronological order.</li></ul><p>Use the category tabs below the charts for category level monthly actuals, annual Plan, Actual and Difference. Difference is Plan minus Actual.</p><p>The annual <b>Left to spend</b> card follows the original workbook calculation: total planned leftover minus total actual leftover. It is a plan comparison, not an account balance or an amount available to spend.</p><h3 class=\"guide-example-title\">Try this example</h3><p>Select Bills in the category table and find Rent. Compare its monthly amounts, then read the annual Plan and Actual columns. If Plan is $14,400 and Actual is $13,800, Difference is $600. This is a comparison with the plan, not necessarily money currently held in an account.</p>"], ["Accounts: balances and reconciliation", "<p>This section combines opening balances with recorded account activity. Deposits are Income; withdrawals are all other transaction types.</p><p><b>Current balance = opening balance + deposits \u2212 withdrawals + adjustments.</b> If an imported backup contains earlier transfers, those transfers also remain in the account calculation, although transfer controls are no longer shown.</p><p>Use Edit to review an account\u2019s opening information and make a reconciliation adjustment. A positive adjustment increases the balance; a negative adjustment reduces it. Last checked records when you compared the account with your own records.</p><p>Account figures are calculated from the activity stored in this budget. They are not connected to your bank. Do not record a transfer as new income unless you intend it to increase your budget income.</p><h3 class=\"guide-example-title\">Try this example</h3><p>With a $1,000 opening balance, $2,000 income and $800 withdrawals, the account shows $2,200. If your own records show $2,190, first look for a missing $10 transaction. Record that transaction if appropriate. Use a $10 negative adjustment only when you intend a balance correction; an adjustment does not create a category expense.</p>"], ["Bill calendar: payments and payday", "<p>Use the combined month/year picker to select the period; click its year to open the year grid. Choose Monday or Sunday as the first day of the week. The calendar reads recurring occurrences from Payment schedule; it does not show variable purchases.</p><p>Income appears as a Payday date header. Click it to review that day\u2019s income occurrences. Other scheduled payments appear inside the day. Paid items are crossed out and faded; overdue and upcoming items retain their status.</p><p>Click a payment to adjust its details or paid status. The top cards show scheduled outflow, paid, remaining and overdue for the selected month, excluding income.</p><p>Days display scheduled payments; scroll the calendar when needed. Weekly totals are not displayed.</p><h3 class=\"guide-example-title\">Try this example</h3><p>Choose September in Bill calendar. A payday date marks scheduled recurring income. Click it to inspect income details. Click the Rent entry to adjust the occurrence or paid status. Paid rent becomes faded and crossed out. Use Variable transactions, rather than this calendar, to enter an unscheduled purchase.</p>"], ["Savings: targets and contributions", "<p>Each savings card represents a goal. Use Edit on an existing card to set its Savings category, starting amount, goal amount, starting date and target date.</p><ul><li><b>Current saved:</b> starting amount plus recorded contributions to that category.</li><li><b>Left to save:</b> target minus current saved.</li><li><b>Progress:</b> current saved divided by target.</li><li><b>Save monthly:</b> target minus starting amount, divided by the original saving period in full months, with a minimum of one month.</li><li><b>Months left:</b> full months from today to the target date.</li></ul><p>The monthly plan is based on the original dates; it does not recalculate a catch up amount after each contribution. Edit the goal or dates to change that plan. Contributions are taken from stored transactions, rather than only the month selected in Monthly budget.</p><p>Click Add goal to open Add category in Settings with Savings selected. This creates a category, not a goal card. Existing goal cards can be configured with Edit.</p><h3 class=\"guide-example-title\">Try this example</h3><p>A $1,400 goal with $200 already saved over 12 full months gives a $100 monthly plan. Record a $100 Savings contribution in the matching category and Current saved becomes $300. Progress is about 21.4% and Left to save is $1,100. The original monthly plan stays $100.</p><p>Use Edit on an existing goal card to set its Savings category, starting amount, target amount and dates. + Add goal opens Add category in Settings with Savings selected. It creates a category only. This version does not expose a separate button to create a new goal card; adding a category does not create one.</p>"], ["Debt payoff: actual payments and your plan", "<p>See what you paid in completed months and what your plan expects you to pay next. Your debt cards, payment tables and charts update together.</p><h3 class=\"guide-example-title\">Step 1: Review your debts</h3><p>Click Edit on a debt card. Enter the amount owed at your Repayment start date, the minimum monthly payment and the annual interest rate. For 18% annual interest, enter 18. Use the same Debt category when recording payments for that debt. \u201c+ Add debt\u201d opens Debt categories in Settings; adding a category alone does not create a debt card.</p><h3 class=\"guide-example-title\">Step 2: Choose your repayment plan</h3><p>Click Show settings next to \u201c+ Add debt\u201d. Set the Repayment start date and Extra monthly payment. Choose Snowball to start with the smallest balance, Avalanche to start with the highest interest rate, or Custom to use your priority order. Hide settings collapses these fields without clearing your choices.</p><h3 class=\"guide-example-title\">Step 3: Use your actual past payments</h3><p>Keep \u201cUse actual payments for past months\u201d checked to use recorded payments for completed calendar months. A recurring payment counts only when marked Paid in Payment schedule. A Debt entry in Variable transactions counts as soon as it is saved. Payments are matched by Debt category and included from the Repayment start date. Do not record the same payment in both places.</p><h3 class=\"guide-example-title\">Step 4: Read Actual and Projected rows</h3><p>Under each debt card, read the Payment and Balance columns. Actual means the payment comes from your records for a completed month. If nothing is recorded, the payment is zero and displays as a dash. Projected means the payment follows your repayment plan. The current month and future months remain projected, even if you have already recorded a payment this month. Cards appear five per row on wide screens and rearrange on smaller screens.</p><h3 class=\"guide-example-title\">Step 5: See how the remaining plan changes</h3><p>A different past payment changes the estimated remaining balance, so the future schedule and payoff date recalculate. For example, if August is a completed month and you recorded $150 instead of the planned $100, August shows $150 as Actual. If you later correct that entry, the schedule updates again. Only the payment is actual: interest and the remaining balance are still calculated estimates, not balances imported from your bank.</p><h3 class=\"guide-example-title\">Step 6: Adjust future payments</h3><p>Change Extra monthly payment for an ongoing extra amount. Use Extra adjustment in the combined Monthly repayment schedule to change the extra amount for one projected month. Actual months cannot be edited through this adjustment field; correct their original transactions instead. Use Details to review the combined payment by debt.</p><h3 class=\"guide-example-title\">Step 7: Switch back to a full projection</h3><p>Uncheck \u201cUse actual payments for past months\u201d if you want every month to follow the original plan. Recorded transactions are kept, and saved monthly adjustments are used again. You can turn the actual payment mode back on at any time.</p><h3 class=\"guide-example-title\">How the estimated balance works</h3><p>The model subtracts the month\u2019s payment first, then applies interest to the remaining balance at the annual rate divided by 12. For example, a $1,000 starting balance with a $150 payment leaves $850 before interest. At 12% annual interest, estimated monthly interest is $8.50, giving an $858.50 balance. A lender may calculate interest differently, so compare the estimate with your statement.</p><p>The forecast runs for up to 372 months. Not reached means the plan has not cleared the debt within that period. Historical payments before the Repayment start date are not deducted again: include their effect in the starting balance.</p><p>Click Edit on a debt card. Enter the amount owed at your Repayment start date, the minimum monthly payment and the annual interest rate. For 18% annual interest, enter 18. Use the same Debt category when recording payments for that debt. + Add debt opens Add category in Settings with Debt selected. It creates a category only. This version does not expose a separate button to create a new debt card; existing cards remain editable.</p>"], ["50/30/20 budget: your allocation", "<p>Choose a month and year with the picker at the top. Cards, charts and category tables include only activity dated within that calendar month. The selected month is shared with Monthly budget and Bill calendar.</p><p>Click Show settings to edit Needs, Wants and Debt &amp; Savings percentages. They must total 100%. Planned amounts use total allocated spending, not income. Income and rollover are excluded.</p><p>Category Budget groups in Settings determine which spending belongs to each group. Paid recurring payments and variable transactions count; unpaid recurring payments do not.</p><h3 class=\"guide-example-title\">Try this example</h3><p>For a month with $2,000 allocated spending, 50/30/20 gives planned amounts of $1,000, $600 and $400. If Needs spending is $1,200, its actual share is 60%. Select another month to see that month\u2019s totals.</p>"], ["Net worth: monthly assets and liabilities", "<p>Net worth is entered independently of Accounts, Savings and Debt payoff. Use Add item to choose a name, side and group. Assets are what you own; liabilities are what you owe. Click an item\u2019s monthly amount to open its balance dialog, then enter the value and click Save changes.</p><p><b>Net worth = assets \u2212 liabilities.</b> Enter liabilities as amounts owed. A blank month means no balance was entered; enter zero explicitly when an item has no remaining value or a debt is fully paid.</p><p>Fill both asset and liability balances for the same month for a comparable snapshot. The top asset and liability cards each use their latest entered month in the selected year; their date labels show if those months differ. Values are not automatically carried into blank months.</p><p>The monthly Net worth table compares totals across the year. Assets breakdown uses the month shown in Total assets. Growth is the difference between an item\u2019s first and latest entered balances.</p><p>Use Show settings to set your Net worth goal. Progress towards goal compares net worth with this target. Left to reach goal shows target minus net worth; a negative result means you have exceeded the goal.</p><h3 class=\"guide-example-title\">Try this example</h3><p>Enter every asset and liability balance in the same month column. With $25,000 assets and $8,000 liabilities, that month\u2019s net worth is $17,000. A $20,000 goal gives 85% progress and $3,000 left to reach it. Next month, enter the new snapshot. Enter 0 for a repaid liability instead of leaving its cell blank.</p>"], ["No spend tracker: your daily habits", "<p>The tracker displays all 12 months of your selected year. Choose Monday or Sunday as the first day of the week.</p><p>In Exclude categories, check the categories that should not count as spending for this tracker. Income is always excluded. These choices change only No spend tracker, not your budget totals.</p><p>A completed day with positive net included spending is a Spending day. A completed day without it is a No spend day. Refunds can offset spending on the same date. Paid recurring payments and variable transactions supply the data.</p><ul><li><b>No spend days:</b> completed days without included net spending.</li><li><b>Spending days:</b> completed days with included net spending.</li><li><b>No spend rate:</b> no spend days divided by completed days.</li><li><b>Longest streak:</b> no spend days in a row.</li></ul><p>Today is still in progress. Today and future dates are excluded from totals and streaks. A past date with no transactions counts as no spend, so keep transactions up to date for a useful result.</p><h3 class=\"guide-example-title\">Try this example</h3><p>If your aim is to avoid optional purchases, check the fixed categories you want to exclude, such as Rent. An included $65 grocery purchase makes September 5 a spending day. If September 6 is complete and has no included spending, it becomes a no spend day. Today never counts toward the completed day totals.</p>"], ["Saving, backups and another device", "<p>Your budget is saved in this browser on this device. There is no automatic cloud, bank or cross device synchronisation. Keep using the same browser and file location for consistent access to its saved data.</p><p>Use Export data in the top bar or Backup to download a JSON backup. Keep the app files as well: the JSON file contains budget data, not the application.</p><p>To restore or move your budget, open the app in the other browser or device and import the JSON through Backup. Import replaces the current budget; it does not merge budgets. Export the current one first if you want to keep it.</p><p>Browser data removal, private browsing or a different file location can affect access to saved data. Export regularly and before switching browsers or resetting the budget. If a save error appears, export a backup before closing the page.</p><p>This edition is designed for desktop and laptop browsers. Phones and tablets are not supported in this release. Opening the app on another computer does not bring its saved data with it.</p><h3 class=\"guide-example-title\">Try this example</h3><p>After entering your first month, click Export data and save the JSON with a recognisable date. To move the budget, open the application on the other device, open Backup and import that JSON. Review the restored totals. Keep the original backup because later changes on the two devices do not synchronise.</p><p>Recovery copies lists up to 10 local safety snapshots made before Clear budget, Reset demo, import or schedule changes. Download copy exports the chosen snapshot; it does not restore it automatically. Dates use your local time zone. These copies share browser storage and do not replace external JSON backups. If a safety copy cannot be stored, the protected action is blocked.</p><p>If the top status says Saving paused, read the warning and download a backup before closing. A conflict with another tab, unreadable saved data or unavailable browser storage can block saving. Keep the current page open until you have a backup; do not assume these changes will survive a reload.</p>"], ["Starting fresh and troubleshooting", "<p>Settings contains options to start with an empty budget or restore demo data. Read the confirmation before proceeding and export a backup first. Starting empty clears recorded activity and plan values while retaining your category, participant and account lists. Restoring the demo replaces the current budget.</p><ul><li><b>A total is zero:</b> check dates, filters, category type and whether recurring payments are marked Paid.</li><li><b>An amount appears twice:</b> look for both a Paid recurring occurrence and a variable entry for the same activity.</li><li><b>A percentage is blank:</b> enter its Plan amount or target; a zero denominator cannot produce a percentage.</li><li><b>A person field is missing:</b> enable Multiple participants in Settings.</li><li><b>A payment is in the wrong month:</b> check its effective date in Adjust, not only the recurring rule\u2019s original date.</li><li><b>Accounts and Net worth differ:</b> Accounts uses recorded activity, while Net worth uses your separately entered monthly balances.</li><li><b>A new Savings or Debt category has no card:</b> categories and configured plan items are separate in this version; the category alone does not supply a goal, balance or repayment terms.</li></ul><p>For help with the template, contact Allocate Studio through Etsy Messages.</p><h3 class=\"guide-example-title\">Try this example</h3><p>If a recurring payment is missing from Monthly budget, open Payment schedule, clear filters and find it. Check its effective date, amount, category and Paid status. If it is also listed in Variable transactions, confirm whether you accidentally entered the same payment twice. Export a backup before deleting or resetting records.</p>"]];return heading('','Help & guide','Everything you need to set up, track and understand your budget.')+panel('Your budget, step by step',`<div class="panel-body faq full-budget-guide">${sections.map(([title,body],i)=>`<details ${i===0?'open':''}><summary>${String(i+1).padStart(2,'0')} · ${title}</summary>${body}</details>`).join('')}</div>`);}


function renderBackup(){let recovery='';try{const copies=recoveryCopies();if(copies.length)recovery=panel('Recovery copies',`<div class="panel-body"><p class="help-text">Copies saved before clearing or replacing this budget. Download a copy to inspect or restore it.</p>${copies.map((c,i)=>`<p>${esc(c.reason)} · ${esc(recoveryDateLabel(c.date))} ${button('Download copy','export-recovery',String(i),'small')}</p>`).reverse().join('')}</div>`);}catch(e){recovery=panel('Recovery copies',`<p class="help-text">${esc(e.message)}</p>`);}return heading('','Backup','Keep a copy of your budget outside this browser.')+recovery+panel('Save and restore',`<div class="panel-body"><p class="explain">Download a copy of your current budget, or restore one you saved earlier. Restoring replaces the budget currently open.</p><p class="backup-status"><b>Last backup:</b> ${backupAgeLabel(backupStatus())}</p><div class="backup-actions">${button('Download backup','export-data','','primary')}${button('Restore from backup','import-data')}</div><p class="help-text">JSON includes settings, categories, accounts, participants, transactions, paid statuses and adjustments, monthly plans, savings goals, debt plans, net worth entries and view preferences. It does not include the application files.</p></div>`)+panel('How to protect your budget',`<div class="panel-body backup-guide"><p>Autosave keeps your working budget in this browser. Downloaded JSON backups let you restore it if that browser data is lost.</p><h3>Step 1: Understand what is saved</h3><p>The app has two separate parts. Its HTML, JavaScript, styles and assets are the application. Your entered budget is saved in this browser’s local storage. Editing the budget does not write your transactions into index.html. Copying the app folder alone does not copy your budget.</p><h3>Step 2: Download your first backup</h3><p>Finish editing your fields and click Save changes if a form is open. On this page, click Download backup. Your browser downloads a JSON file containing your current budget. If it asks where to save, choose your backup folder. Otherwise check the browser’s Downloads list. Starting the download is not proof that the file reached your chosen folder: check that it is there.</p><h3>Step 3: Keep copies outside the browser</h3><p>Keep dated JSON backups in a folder you can find, with another copy on an external drive or in your own secure cloud storage. Keep several versions instead of replacing your only copy. The backup contains financial information in readable text; it is not password protected. Do not share it publicly.</p><h3>Step 4: Make backups part of your routine</h3><p>Download a new backup after each session with important changes and at least weekly while using the budget. Always export before clearing browser data, switching browsers or devices, moving or renaming the app folder, importing another budget, installing an updated app or using Reset demo or Clear budget. Export is manual; the app does not automatically create files in your backup folder.</p><h3>Step 5: Restore a saved budget</h3><p>First download a backup of the budget currently open, if you need to keep it. Click Restore from backup and select an Allocate Studio JSON export, not index.html, a ZIP or a spreadsheet. The app checks the file and asks for confirmation. Confirm only when you want its contents to replace the current budget. Import replaces; it does not merge. Check the budget name, dates, recent transactions and balances afterward.</p><h3>Step 6: Move to another device or browser</h3><p>Copy the complete app folder and your latest JSON backup. Open index.html from the extracted app folder in the destination browser. Open Backup and restore the JSON. Check the restored values before continuing. Changes on the old and new devices do not synchronise. Choose one as your main working copy to avoid two different versions.</p><h3>Step 7: Update the application</h3><p>Before opening an update, export your latest budget from the old version and keep the old app folder. Extract the complete new app into a separate folder, open it, and restore your backup if your data is not shown. Import compatibility is checked by the app; it is not guaranteed for every future version. If import fails, keep the backup unchanged and return to the old version. Do not delete the old folder or backup until you have checked the new version.</p><h3>Step 8: If your data seems missing</h3><p>Stay in the same browser and browser profile you originally used, and try the original app file location. Do not reset or enter replacement data immediately. A different browser, profile, private window or file location may open separate storage. If the original stored data is unavailable, restore your latest JSON. Only changes included in that backup can be recovered; the seller does not hold a copy of your local budget.</p><h3>Step 9: If the browser cannot save</h3><p>If the top status says Saving paused or you see a save warning, keep the page open and download a backup immediately. Do not assume closing and reopening will preserve those changes. Avoid private or incognito mode for daily use. Browser storage can be cleared or become unavailable. A JSON copy outside the browser is your recovery file.</p><h3>Step 10: Check your backup before you need it</h3><p>After your first export, confirm that the file is present and not empty. For a recovery test, open the app in a separate browser profile with no budget you need to preserve and import a copy of the JSON. Compare the budget dates, transaction amounts and balances with the original. Keep using your original working profile after the test. This check validates that snapshot, not later changes.</p></div>`);}

window.BudgetViews={backup:renderBackup,monthly:renderMonthly,recurring:renderRecurring,payments:renderPayments,variable:renderVariable,calendar:renderCalendar,accounts:renderAccounts,savings:renderSavings,debt:renderDebt,allocation:renderAllocation,networth:renderNetWorth,setup:renderSetup,help:renderHelp};

const pageGuides={"recurring": {"title": "Set up your recurring transactions", "intro": "This is where your regular income and bills live. Enter anything that repeats once, and your budget creates the payment dates for you.", "steps": [["Add your first item", "Click \u201c+ Add recurring\u201d. Choose a transaction type, then a category. For example, choose Bills and Rent for your monthly rent, or Income and Salary for your regular pay. If a category is missing, add it in Settings first."], ["Set the amount and schedule", "Enter the amount of one payment and choose how often it repeats. For monthly rent of $1,200, enter 1200 and select Every Month. Set First payment to the first date it is due. Leave Last payment blank if it continues, or enter the date it stops."], ["Choose who and which account", "Select the account the money comes from or arrives in. If you chose multiple participants in Settings, select the person too. Click \u201cSave changes\u201d. Your recurring item now appears in the list."], ["Mark each payment as it happens", "Open Payments & recurring from the menu and stay on the Payment schedule tab. Tick Paid when a bill is paid or income arrives. Creating a recurring item does not count it as actual money received or spent until you mark its payment Paid."], ["Make changes when you need to", "Use Edit here to change the recurring setup. To change just one payment, use Adjust in Payment schedule instead. Paid twice on fixed dates each month? Add two Every Month items, one for each payday. When changing First payment, Last payment or Frequency, choose Keep recorded payments or Rebuild payments through today. Rebuild replaces the selected rule\u2019s recorded schedule and marks scheduled payments through today as paid; review this choice carefully. A recovery copy is required before the schedule change."]]}, "variable": {"title": "Log your everyday transactions", "intro": "Use this page for anything that does not repeat on a schedule. Groceries, a meal out, a gift or extra income can all go here.", "steps": [["Add a transaction", "Click \u201c+ Add transaction\u201d. Enter the date it happened. Choose the type and category, such as Expenses and Groceries. Categories come from your lists in Settings."], ["Fill in the details", "Enter the amount, then choose the account you used. Select a person if that field is shown. Add a description if helpful, such as \u201cWeekly groceries\u201d, then click \u201cSave changes\u201d. An amount of zero requires a description. A negative amount in a spending category records a refund."], ["See it in your budget", "Your entry counts immediately. A $65 grocery purchase dated September 5 adds $65 to September\u2019s grocery spending and the selected account\u2019s withdrawals. There is no Paid checkbox on this page."], ["Find and correct an entry", "Use search or the filters above the table to find what you need. Click Edit to correct an entry. Click Clear to remove the filters. Do not enter a payment here if you have already marked the same payment Paid in Payment schedule."]]}, "payments": {"title": "Keep track of your payments", "intro": "Your recurring items appear here as individual dated payments. Use this list to see what is coming up and check off what is done.", "steps": [["Find the payment", "If the list is empty, add your regular income and bills in Recurring transactions first. Use the filters to choose a month, type, account or status. Click Clear to see the full list again. Choose an available report year at the top. + Open next year extends the latest available year, up to 2199."], ["Tick Paid when it happens", "Tick the Paid checkbox when money leaves your account or income arrives. The payment now counts in your actual budget totals. Untick it if you checked it by mistake. An unpaid payment before today is shown as Overdue."], ["Adjust just this payment", "Click Adjust if this occurrence has a different date, amount, account or person. Fill in only what changed and save. For example, change this month\u2019s rent from $1,200 to $1,250 without changing future rent payments. Blank uses the original value; 0 is a valid new amount."], ["Review what is left", "The cards above the table show scheduled payments, paid amounts, remaining amounts and overdue amounts for your current filters. They exclude income. A payment counts in the month of its adjusted date, including a future month if you mark it Paid early."]]}, "monthly": {"title": "Plan and review your month", "intro": "This is where you decide what you expect to earn and spend, then compare it with what actually happened.", "steps": [["Choose your month", "Click the month and year button to open the month grid. Use the header arrows to change year, or click the year to choose from the year grid. The arrows beside the button step one month. This month selects the current month when available. Escape closes the picker. In Monthly budget, unavailable months are disabled. Use + Add month in the picker to create a planning month. In the category tables, click a Plan amount, enter your amount in the dialog and click Save changes."], ["Review your rollover", "Click Show settings to see the previous month\u2019s remaining balance. It is carried forward automatically, including a negative balance. Uncheck Carry over previous month\u2019s balance to start this month from zero. Earlier transaction changes recalculate rollover. With no earlier activity, rollover is zero. Turning rollover off resets the incoming balance for this month only; the following month carries forward the balance of this new chain. Rollover is not a new income transaction."], ["Record your income and spending", "Add everyday entries in Variable transactions. For regular bills and income, mark the occurrences Paid in Payment schedule. The Actual columns update automatically. You do not need to enter the same amounts again here."], ["Check how your plan is going", "Compare Plan and Actual in Budget summary. Budget remaining shows how much of your spending plan is left. With a $2,000 plan and $1,500 spent, it shows $500 remaining and 75% used. Spending includes Bills, Expenses, Debt and Savings."], ["Read your available balance", "Available to spend uses income minus spending, plus rollover if enabled. It can differ from Budget remaining because one uses your income and the other uses your plan. The daily chart shows when your balance rose or fell."]]}, "annual": {"title": "See your whole selected year", "intro": "This is your big picture. It brings together the twelve months of your selected year so you can spot patterns without entering anything here.", "steps": [["Choose a year", "Use the year menu at the top. Reports show January through December. Switching years keeps all saved data and plans, and you can return to any previous year."], ["Start with the totals", "Read the cards at the top for annual income, spending, savings contributions and debt payments. These update from your recorded transactions. If something is missing, check the transaction date and whether its recurring payment is marked Paid."], ["Compare the months", "Use the charts to see income and spending over time. Budget vs actual compares planned leftover with actual leftover. Running balance adds up income minus spending across the year, without adding monthly rollover again."], ["Look at one type", "In Monthly overview, choose Income, Bills, Expenses, Debt or Savings from the dropdown. The chart shows that type\u2019s amounts month by month. Cash flow summary gives you the monthly numbers in a table."], ["Check the category detail", "Choose a category tab below the charts, then read across a row. Plan is the total you planned, Actual is what you recorded, and Difference is Plan minus Actual. To change a plan, open Monthly budget. To correct actuals, edit the original transaction."], ["Understand the Left to spend card", "This card compares total planned leftover with total actual leftover, using the original workbook formula. It is not your bank balance. Use Accounts to review account balances."]]}, "calendar": {"title": "See your month on a calendar", "intro": "See when your regular payments are due and where your paydays fall, all in one place.", "steps": [["Choose the month", "Click the month and year button to open the month grid. Use the header arrows to change year, or click the year to choose from the year grid. The arrows beside the button step one month. This month selects the current month when available. Escape closes the picker. Bill calendar uses this combined month/year picker, without a separate year menu. Choose Monday or Sunday as the first day of the week. The calendar shows recurring payments, not variable transactions."], ["Read each day", "Bills and other scheduled payments appear inside the day. Paid entries are crossed out and faded. Payday appears in the date header when recurring income is scheduled. Click Payday to see that day\u2019s income details."], ["Update a payment", "Click a payment to open its details. Mark it Paid when completed, or adjust its date or amount if something changed. The calendar and budget totals update after saving."], ["Check what is still due", "The top cards show total scheduled outgoings, paid, remaining and overdue for this month. Income is excluded from these totals. Everyday purchases belong in Variable transactions and do not appear in this calendar."]]}, "accounts": {"title": "Review your account balances", "intro": "Keep a simple record of how much is in each account using your opening balances and the transactions you log.", "steps": [["Add or review your accounts", "Click \u201c+ Add account\u201d, or Edit next to an existing account. Give it a recognisable name and enter its opening balance, meaning the amount before the activity you are tracking. Do not also record that opening amount as income."], ["Choose the account on transactions", "When you add income or a payment, select the account it belongs to. Income appears as Deposits. Bills, Expenses, Debt and Savings appear as Withdrawals. Paid recurring payments and variable transactions feed these totals."], ["Compare with your own records", "An opening balance of $1,000, deposits of $2,000 and withdrawals of $800 produce a $2,200 balance before adjustments. Compare the result with your bank records. This page does not connect to your bank automatically."], ["Correct a difference", "Look for missing or duplicate transactions first. If you need a balance correction, use Edit to enter an adjustment and Last checked date. Positive adjustments increase the balance; negative adjustments reduce it. An adjustment does not add a category expense."]]}, "savings": {"title": "Follow your savings goals", "intro": "See how much you have saved for each goal and the monthly pace of your original plan.", "steps": [["Review a goal", "Use Edit on an existing goal card to set its Savings category, starting amount, target amount and dates. + Add goal opens Add category in Settings with Savings selected. It creates a category only. This version does not expose a separate button to create a new goal card; adding a category does not create one."], ["Record money you put aside", "Add a Savings transaction in Variable transactions and select the category linked to the goal. If the contribution repeats, set it up in Recurring transactions and mark each occurrence Paid in Payment schedule."], ["Watch your progress update", "Current saved combines your starting amount and recorded contributions. If you began with $200 and add $100, the card shows $300 saved. Left to save tells you how much is still needed for the target."], ["Review the monthly target", "Save monthly uses your original target and saving dates. A $1,400 goal with $200 already saved over 12 full months gives a $100 monthly target. It does not change into a catch-up plan after each contribution. Edit the goal or dates if you want to change the pace."]]}, "debt": {"title": "Track and plan your debt payments", "intro": "See what you paid in completed months and what your plan expects you to pay next. Your debt cards, payment tables and charts update together.", "steps": [["Review your debts", "Click Edit on a debt card. Enter the amount owed at your Repayment start date, the minimum monthly payment and the annual interest rate. For 18% annual interest, enter 18. Use the same Debt category when recording payments for that debt. + Add debt opens Add category in Settings with Debt selected. It creates a category only. This version does not expose a separate button to create a new debt card; existing cards remain editable."], ["Choose your repayment plan", "Click Show settings next to \u201c+ Add debt\u201d. Set the Repayment start date and Extra monthly payment. Choose Snowball to start with the smallest balance, Avalanche to start with the highest interest rate, or Custom to use your priority order. Hide settings collapses these fields without clearing your choices."], ["Use your actual past payments", "Keep \u201cUse actual payments for past months\u201d checked to use recorded payments for completed calendar months. A recurring payment counts only when marked Paid in Payment schedule. A Debt entry in Variable transactions counts as soon as it is saved. Payments are matched by Debt category and included from the Repayment start date. Do not record the same payment in both places."], ["Read Actual and Projected rows", "Under each debt card, read the Payment and Balance columns. Actual means the payment comes from your records for a completed month. If nothing is recorded, the payment is zero and displays as a dash. Projected means the payment follows your repayment plan. The current month and future months remain projected, even if you have already recorded a payment this month. Cards appear five per row on wide screens and rearrange on smaller screens."], ["See how the remaining plan changes", "A different past payment changes the estimated remaining balance, so the future schedule and payoff date recalculate. For example, if August is a completed month and you recorded $150 instead of the planned $100, August shows $150 as Actual. If you later correct that entry, the schedule updates again. Only the payment is actual: interest and the remaining balance are still calculated estimates, not balances imported from your bank."], ["Adjust future payments", "Change Extra monthly payment for an ongoing extra amount. Use Extra adjustment in the combined Monthly repayment schedule to change the extra amount for one projected month. Actual months cannot be edited through this adjustment field; correct their original transactions instead. Use Details to review the combined payment by debt."], ["Switch back to a full projection", "Uncheck \u201cUse actual payments for past months\u201d if you want every month to follow the original plan. Recorded transactions are kept, and saved monthly adjustments are used again. You can turn the actual payment mode back on at any time."]]}, "allocation": {"title": "Check your 50/30/20 split", "intro": "See how your recorded spending divides between Needs, Wants and Debt & Savings.", "steps": [["Choose the period", "Choose the month and year using the picker at the top, as in Monthly budget. Click the year inside the picker to choose another year. All cards, charts and category tables use the selected calendar month, from its first through its last day. There is no custom date range."], ["Set your target split", "Keep 50% for Needs, 30% for Wants and 20% for Debt & Savings, or enter your own percentages. The three numbers must add up to 100% before the new split saves."], ["Compare with your actual spending", "Read the charts and cards to see each group\u2019s actual share beside its target. With $2,000 of allocated spending, a 50% Needs target is $1,000. This view uses allocated spending as its base, not income."], ["Find what is driving the result", "Look through the three category tables. If a category is in the wrong group, open Settings, edit that category and change its Budget group. It then moves to the correct group here."]]}, "networth": {"title": "Track what you own and owe", "intro": "Enter a monthly snapshot of your assets and liabilities to see your net worth over time.", "steps": [["Add your items", "Click \u201c+ Add item\u201d. Enter a name, choose Asset or Liability and select a group. Assets are things you own, such as cash, investments or property. Liabilities are amounts you owe, such as a credit card balance or loan."], ["Fill in one month", "Click an item\u2019s amount in the month column to open its balance dialog, enter the balance and click Save changes. Enter liabilities as positive amounts owed. Enter 0 for a fully repaid debt; leave the field blank only when no balance is recorded."], ["Set your goal", "Click Show settings and enter the net worth amount you are aiming for. If your assets are $25,000 and liabilities are $8,000, net worth is $17,000. Against a $20,000 goal, that is 85% progress with $3,000 to go."], ["Come back next month", "Enter a fresh set of monthly balances when you review your accounts. Charts and tables update from those entries. Values are not copied into empty months and do not sync with Accounts or Debt payoff. Check the dates on the top cards because assets and liabilities can use different latest entered months."]]}, "nospend": {"title": "Track your days without spending", "intro": "Use this calendar to spot your spending habits and build a run of days without the purchases you want to avoid.", "steps": [["Choose what counts", "In Exclude categories, check anything you want the tracker to ignore. For example, exclude Rent if your goal is to avoid everyday purchases rather than scheduled bills. Income is always excluded. Other budget totals are not changed."], ["Keep recording your activity", "Add purchases in Variable transactions and mark recurring payments Paid as usual. The tracker reads those records automatically. There is nothing to tick on each calendar day."], ["Read your calendar", "A completed day with positive included spending is a spending day. A completed day without it is a no spend day. Refunds can offset spending on the same day. Today is still in progress, and future dates are not counted."], ["Follow your streak", "The cards show no spend days, spending days, the no spend rate and your longest run of no spend days in a row. Keep transactions up to date: a past day with no recorded activity also counts as no spend."]]}, "setup": {"title": "Make this budget your own", "intro": "Start here before logging your first transactions. The names you enter become the choices throughout your budget.", "steps": [["Choose your budget preferences", "Enter a budget name, currency, currency position and first day of the week. Choose Custom for your own currency symbol. Currency changes display only, not amounts. There is no start month or start year field in Settings. The first recorded activity sets the initial reporting period; an empty budget starts with the current year. Report year menus list years from budget data and opened payment years. Monthly budget uses available months; + Add month creates a planning month without moving existing records."], ["Choose who uses the budget", "Select One participant for a personal budget. Select Multiple participants if you share it, then add or edit the names. This adds a person selection to transaction forms and tables. Switching back to one participant hides that field without deleting earlier assignments."], ["Add your accounts", "Enter recognisable names, such as Everyday Checking or Cash, choose each account type and enter its opening balance. Click Add account to open the form, enter the details and click Save changes. Use Edit beside an existing account to update it. The opening balance is what you had before the transactions you will record."], ["Set up your categories", "Add or rename the categories you need under Income, Bills, Expenses, Debt and Savings. Choose a Budget group for each spending category. Rent might be Needs, Dining Out might be Wants, and Retirement might be Debt & Savings."], ["Save a backup", "Inline settings save when you change a selection or leave a field. Forms save with Save changes. Export data regularly and before starting fresh. Switching report periods does not move or clear transactions. If the top status says Saving paused, read the warning and download a backup before closing."]]}, "help": {"title": "Find your way around", "intro": "You can read the full guide here or open a short guide from any budget page.", "steps": [["Start with Settings", "Choose your participants, accounts and categories. The start date comes from your first transaction. This gives the transaction forms the names and choices you need."], ["Build your routine", "Add repeating income and bills in Recurring transactions. Mark individual occurrences Paid in Payment schedule. Use Variable transactions for everyday purchases and other activity that does not repeat."], ["Plan and review", "Enter Plan amounts in Monthly budget, then use your dashboards to compare the plan with actual activity. On any page, click \u201cHow to use\u201d for steps specific to that page."], ["Read more when needed", "Open a section below for the full explanation and a worked example. Export data regularly to keep a backup you can restore through Backup."]]}, "backup": {"title": "Keep a safe copy of your budget", "intro": "Autosave keeps your working budget in this browser. Downloaded JSON backups let you restore it if that browser data is lost.", "steps": [["Download your first backup", "Finish editing your fields and click Save changes if a form is open. On this page, click Download backup. Your browser downloads a JSON file containing your current budget. If it asks where to save, choose your backup folder. Otherwise check the browser\u2019s Downloads list. Starting the download is not proof that the file reached your chosen folder: check that it is there."], ["Keep copies outside the browser", "Keep dated JSON backups in a folder you can find, with another copy on an external drive or in your own secure cloud storage. Keep several versions instead of replacing your only copy. The backup contains financial information in readable text; it is not password protected. Do not share it publicly."], ["Restore a saved budget", "First download a backup of the budget currently open, if you need to keep it. Click Restore from backup and select an Allocate Studio JSON export, not index.html, a ZIP or a spreadsheet. The app checks the file and asks for confirmation. Confirm only when you want its contents to replace the current budget. Import replaces; it does not merge. Check the budget name, dates, recent transactions and balances afterward."], ["If the browser cannot save", "If the top status says Saving paused, read the warning and download a backup before closing. A conflict with another tab, unreadable saved data or unavailable browser storage can block saving. Keep the current page open until you have a backup; do not assume these changes will survive a reload."], ["Use recovery copies", "Recovery copies lists up to 10 local safety snapshots made before Clear budget, Reset demo, import or schedule changes. Download copy exports the chosen snapshot; it does not restore it automatically. Dates use your local time zone. These copies share browser storage and do not replace external JSON backups. If a safety copy cannot be stored, the protected action is blocked."]]}};
function showPageGuide(id){const guide=pageGuides[id]||pageGuides.help;openDialog(guide.title,`<div class="page-quick-guide"><p class="quick-guide-intro">${esc(guide.intro)}</p>${guide.steps.map(([title,text],i)=>`<section class="quick-guide-step"><h3>Step ${i+1}: ${esc(title)}</h3><p>${esc(text)}</p></section>`).join('')}<div class="quick-guide-close">${button('Close','close-page-guide')}</div></div>`,()=>{});}

pageGuides.monthly.steps.splice(1,0,["Reuse last month’s plan","Open Show settings in Monthly budget, then click Copy previous month beside the rollover controls to preview the category plan totals from the previous calendar month. Save changes replaces this month’s category plans. Actual transactions and rollover settings stay unchanged. You can edit individual Plan amounts afterward."]);
